  const EXPLAIN = [['en', 'English'], ['el', 'Ελληνικά'], ['de', 'Deutsch'], ['fr', 'Français'], ['es', 'Español'], ['it', 'Italiano'], ['ru', 'Русский'], ['tr', 'Türkçe']];   // i18n-ignore (endonyms)
